background_integration.opening_selector:
// In background.js
const openTabSelector = async (windowId, newTabId) => {
  const popup = await chrome.windows.create({
    url: `selector.html?windowId=${windowId}&newTabId=${newTabId}`,
    type: 'popup',
    width: 400,
    height: 500,
    left: Math.round((screen.width - 400) / 2),
    top: Math.round((screen.height - 500) / 2),
    focused: true
  });
  return popup.id;
}

background_integration.message_handling:
// Listen for selection
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === 'tabSelected') {
    chrome.tabs.remove(request.tabId);
    chrome.windows.remove(sender.tab.windowId);
  } else if (request.action === 'cancelSelection') {
    chrome.tabs.remove(request.newTabId);
    chrome.windows.remove(sender.tab.windowId);
  }
});

code_examples.selector.js_init:
// Get params from URL
const params = new URLSearchParams(window.location.search);
const windowId = parseInt(params.get('windowId'));
const newTabId = parseInt(params.get('newTabId'));

// Load tabs for this window
chrome.tabs.query({windowId: windowId}, (tabs) => {
  displayTabs(tabs.filter(t => t.id !== newTabId));
});
